mapper.select:
SELECT * FROM biz_practical_ai_job
WHERE teacher_user_id=#{teacherUserId} AND lesson_id=#{lessonId} AND question_id=#{questionId}
  AND entry_year=#{entryYear} AND class_code=#{classCode}
  AND job_status IN ('PENDING','RUNNING','PAUSED','CANCEL_REQUESTED')
ORDER BY job_id DESC LIMIT 1

SELECT * FROM biz_practical_ai_job
WHERE teacher_user_id=#{teacherUserId} AND lesson_id=#{lessonId} AND question_id=#{questionId}
  AND entry_year=#{entryYear} AND class_code=#{classCode}
ORDER BY job_id DESC LIMIT 1

SELECT event_id,job_id,result_id,event_level,event_stage,event_message,create_time
FROM biz_practical_ai_event
WHERE job_id=#{jobId}
AND event_id > #{afterEventId}
ORDER BY event_id DESC LIMIT #{limit}

mapper.update:
UPDATE biz_practical_ai_result
SET apply_status=#{applyStatus}, applied_by_user_id=#{appliedByUserId,jdbcType=BIGINT},
    applied_time=#{appliedTime,jdbcType=TIMESTAMP}
WHERE result_id=#{resultId}

